CREATE TABLE IF NOT EXISTS public.artists (
  id text PRIMARY KEY,
  name text NOT NULL,
  avatar text NOT NULL DEFAULT '',
  cover_image text,
  role text NOT NULL DEFAULT '',
  bio text NOT NULL DEFAULT '',
  genres jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_verified boolean NOT NULL DEFAULT false,
  total_streams integer NOT NULL DEFAULT 0,
  tracks_count integer NOT NULL DEFAULT 0,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.artists TO anon, authenticated;
GRANT ALL ON public.artists TO service_role;
ALTER TABLE public.artists ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Read Artists" ON public.artists;
CREATE POLICY "Public Read Artists" ON public.artists FOR SELECT USING (true);

GRANT SELECT ON public.tracks, public.categories, public.site_settings TO anon, authenticated;
GRANT INSERT ON public.order_logs, public.analytics_events TO anon, authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.analytics_events_id_seq TO anon, authenticated;
GRANT ALL ON public.tracks, public.categories, public.site_settings, public.order_logs, public.analytics_events TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public.analytics_events_id_seq TO service_role;

